const row = $input.first().json;
const cats = Array.isArray(row.categories) ? row.categories : JSON.parse(row.categories || '[]');

// Parse histórico recente
let history = [];
try {
  history = Array.isArray(row.recent_history) ? row.recent_history : JSON.parse(row.recent_history || '[]');
} catch(e) {}

// Montar resumo do histórico (ordem cronológica: mais antigo primeiro, mais recente por último)
const historyText = history
  .map(m => `[${m.role === 'human' ? 'USUÁRIO' : 'BOT'}]: ${m.text}`)
  .join('\n');

// Captura quoted_message (reply do WhatsApp)
const quotedMessage = $('[SET] Padronizacao1').first().json.quoted_message || '';

const replyBlock = quotedMessage
  ? `\n⚡ REPLY DETECTADO — O usuário fez reply na seguinte mensagem do bot:\n"""\n${quotedMessage}\n"""\nEssa mensagem citada é a fonte de verdade para identificar a tarefa ou contexto. Use-a ANTES do histórico.\n`
  : '';

const summary = [
  `Horários padrão: manhã=${row.time_manha||'11:00'}, tarde=${row.time_tarde||'17:00'}, noite=${row.time_noite||'20:30'}, dia=${row.time_dia||'15:00'}`,
  `Relatório manhã: ${row.report_manha ? 'ativado' : 'desativado'}`,
  `Categorias disponíveis: ${cats.join(', ')}`,
  replyBlock,
  `\n--- HISTÓRICO RECENTE (últimas mensagens, ordem cronológica — a ÚLTIMA linha é a mais recente) ---`,
  historyText || '(sem histórico)'
].join('\n');

return [{ json: { ...row, context_summary: summary, category_names: cats } }];

