SELECT name, is_default FROM categories
WHERE user_phone = '{{ $('[SET] Padronizacao1').first().json.number }}'
ORDER BY is_default DESC, name;

UPDATE tasks SET status = 'archived', updated_at = now()
WHERE id = {{ $fromAI('task_id','ID numérico da tarefa','number') }}
  AND user_phone = '{{ $('[SET] Padronizacao1').first().json.number }}'
RETURNING id, title;

